package com.university;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

/**
 * DatabaseUtil — Manages PostgreSQL database connectivity for Neon.
 * 
 * Automatically loads connection details from:
 * 1. .env.local or .env file (generated by 'neon deploy')
 * 2. System environment variables (DATABASE_URL, POSTGRES_URL, PGHOST, etc.)
 */
public class DatabaseUtil {

    private static final Map<String, String> ENV_CACHE = new HashMap<>();
    private static boolean envLoaded = false;

    static {
        loadDotEnv();
        try {
            Class.forName("org.postgresql.Driver");
        } catch (ClassNotFoundException ignored) {
            // Driver will be auto-loaded via ServiceLoader if present on classpath
        }
    }

    private static synchronized void loadDotEnv() {
        if (envLoaded) return;
        envLoaded = true;

        String[] searchPaths = new String[] {
            ".env.local",
            ".env",
            "../.env.local",
            "../.env",
            "../../.env.local",
            "../../.env"
        };

        for (String p : searchPaths) {
            File f = new File(p);
            if (f.exists() && f.isFile()) {
                parseEnvFile(f);
            }
        }
    }

    private static void parseEnvFile(File file) {
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) continue;
                int eq = line.indexOf('=');
                if (eq > 0) {
                    String key = line.substring(0, eq).trim();
                    String val = line.substring(eq + 1).trim();
                    if ((val.startsWith("\"") && val.endsWith("\"")) ||
                        (val.startsWith("'") && val.endsWith("'"))) {
                        val = val.substring(1, val.length() - 1);
                    }
                    ENV_CACHE.putIfAbsent(key, val);
                }
            }
        } catch (Exception e) {
            System.err.println("Note: Could not parse env file " + file.getPath() + ": " + e.getMessage());
        }
    }

    public static String getEnv(String key, String defaultValue) {
        loadDotEnv();
        String val = System.getenv(key);
        if (val != null && !val.isBlank()) return val;
        val = System.getProperty(key);
        if (val != null && !val.isBlank()) return val;
        val = ENV_CACHE.get(key);
        if (val != null && !val.isBlank()) return val;
        return defaultValue;
    }

    public static class DbInfo {
        public String jdbcUrl;
        public String user;
        public String password;
    }

    public static DbInfo getDbInfo() {
        DbInfo info = new DbInfo();
        String raw = getEnv("DATABASE_URL", getEnv("POSTGRES_URL", null));
        String user = getEnv("PGUSER", null);
        String pass = getEnv("PGPASSWORD", null);
        String url = null;

        if (raw != null && !raw.isBlank()) {
            String normalized = raw;
            if (normalized.startsWith("jdbc:")) {
                normalized = normalized.substring("jdbc:".length());
            }

            if (normalized.startsWith("postgresql://") || normalized.startsWith("postgres://")) {
                int schemeEnd = normalized.indexOf("://") + 3;
                String rest = normalized.substring(schemeEnd);
                int atIndex = rest.indexOf('@');
                if (atIndex != -1) {
                    String userInfo = rest.substring(0, atIndex);
                    rest = rest.substring(atIndex + 1);
                    int colonIndex = userInfo.indexOf(':');
                    if (colonIndex != -1) {
                        if (user == null) user = URLDecoder.decode(userInfo.substring(0, colonIndex), StandardCharsets.UTF_8);
                        if (pass == null) pass = URLDecoder.decode(userInfo.substring(colonIndex + 1), StandardCharsets.UTF_8);
                    } else {
                        if (user == null) user = URLDecoder.decode(userInfo, StandardCharsets.UTF_8);
                    }
                }
                url = "jdbc:postgresql://" + rest;
            } else {
                url = raw;
            }
        }

        if (url == null) {
            String host = getEnv("PGHOST", "localhost");
            String port = getEnv("PGPORT", "5432");
            String db = getEnv("PGDATABASE", "neondb");
            String ssl = getEnv("PGSSLMODE", "require");
            url = "jdbc:postgresql://" + host + ":" + port + "/" + db;
            if (ssl != null && !ssl.isBlank()) {
                url += "?sslmode=" + ssl;
            }
        }

        if (!url.contains("sslmode=")) {
            url += (url.contains("?") ? "&" : "?") + "sslmode=require";
        }

        info.jdbcUrl = url;
        info.user = user;
        info.password = pass;
        return info;
    }

    public static String getJdbcUrl() {
        return getDbInfo().jdbcUrl;
    }

    public static Connection getConnection() throws SQLException {
        DbInfo info = getDbInfo();
        Properties props = new Properties();
        if (info.user != null) {
            props.setProperty("user", info.user);
        }
        if (info.password != null) {
            props.setProperty("password", info.password);
        }
        return DriverManager.getConnection(info.jdbcUrl, props);
    }

    /**
     * Creates database tables (programs, students) if they do not exist
     * and seeds initial academic programs.
     */
    public static void initializeDatabase() throws SQLException {
        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) {

            // Create programs table
            stmt.executeUpdate(
                "CREATE TABLE IF NOT EXISTS programs (" +
                "  program_id SERIAL PRIMARY KEY," +
                "  program_name VARCHAR(100) NOT NULL," +
                "  required_units INT NOT NULL" +
                ")"
            );

            // Create students table
            stmt.executeUpdate(
                "CREATE TABLE IF NOT EXISTS students (" +
                "  student_id SERIAL PRIMARY KEY," +
                "  registration_number VARCHAR(20) UNIQUE NOT NULL," +
                "  first_name VARCHAR(50) NOT NULL," +
                "  last_name VARCHAR(50) NOT NULL," +
                "  email VARCHAR(100) UNIQUE NOT NULL," +
                "  program_id INT REFERENCES programs(program_id)" +
                ")"
            );

            // Seed default programs if table is empty
            try (ResultSet rs = stmt.executeQuery("SELECT COUNT(*) FROM programs")) {
                if (rs.next() && rs.getInt(1) == 0) {
                    stmt.executeUpdate(
                        "INSERT INTO programs (program_name, required_units) VALUES " +
                        "('Bachelor of Computer Science', 56), " +
                        "('Diploma in IT', 24)"
                    );
                    System.out.println("Default programs seeded successfully.");
                }
            }
            System.out.println("Neon PostgreSQL database tables initialized successfully.");
        }
    }
}
